   switch(topic){case "alyx-liquid-shader":Bottle(d);break;case "batman-origins-snow-below-camera":Snow(d);break;case "sea-of-thieves-water-masking":Boat(d);break;case "uncharted3-fixed-plane-scrolling-desert":Plane(d);break;case "uncharted4-taut-rope-fallback":Rope(d);break;case "starcraft-worker-mineral-walk":Workers(d);break;case "starcraft2-marine-random-firing-delay":Marines(d);break;default:throw new Exception(topic);}
