  static Transform Knight(){string p="Assets/ThirdParty/KayKitAdventurers/";var src=AssetDatabase.LoadAssetAtPath<GameObject>(p+"Knight.fbx");if(!src)throw new Exception("Licensed Knight missing");var g=(GameObject)PrefabUtility.InstantiatePrefab(src);g.name="Articulated walker";foreach(var a in g.GetComponentsInChildren<Animator>())a.enabled=false;var m=Mat("knight",Color.white);m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(p+"knight_texture.png");foreach(var r in g.GetComponentsInChildren<Renderer>())r.sharedMaterial=m;g.transform.localScale=Vector3.one*.8f;return g.transform;}
  static void Snow(TechTenDemo d){const int n=96;var v=new Vector3[(n+1)*(n+1)];var uv=new Vector2[v.Length];var tri=new int[n*n*6];for(int z=0;z<=n;z++)for(int x=0;x<=n;x++){int i=z*(n+1)+x;v[i]=new Vector3((x/(float)n-.5f)*8,.12f,(z/(float)n-.5f)*4);uv[i]=new Vector2(x/(float)n,z/(float)n);}int k=0;for(int z=0;z<n;z++)for(int x=0;x<n;x++){int a=z*(n+1)+x;foreach(int q in new[]{a,a+n+1,a+1,a+1,a+n+1,a+n+2})tri[k++]=q;}
   var mesh=new Mesh{name="Deformable snow teaching mesh"};mesh.vertices=v;mesh.uv=uv;mesh.triangles=tri;mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,Root+"/Meshes/"+prefix+".asset");var g=new GameObject("Accumulated contact height surface");d.dynamicSurface=g.AddComponent<MeshFilter>();d.dynamicSurface.sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=Mat("snow",new Color(.83f,.91f,.98f));
   var knight=Knight();knight.rotation=Quaternion.Euler(0,90,0);foreach(var t in knight.GetComponentsInChildren<Transform>())t.gameObject.layer=9;d.actors=new[]{knight};d.walk=AssetDatabase.LoadAllAssetsAtPath("Assets/ThirdParty/KayKitAdventurers/Knight.fbx").OfType<AnimationClip>().FirstOrDefault(a=>a.name.ToLower().Contains("walk"));if(!d.walk)throw new Exception("Walking clip required for the snow example");
   d.contactCamera=new GameObject("Actual orthographic contact camera").AddComponent<Camera>();d.contactCamera.transform.position=new Vector3(0,-3,0);d.contactCamera.transform.rotation=Quaternion.LookRotation(Vector3.up,Vector3.forward);d.contactCamera.orthographic=true;d.contactCamera.orthographicSize=2;d.contactCamera.aspect=2;d.contactCamera.nearClipPlane=2.98f;d.contactCamera.farClipPlane=3.3f;d.contactCamera.cullingMask=1<<9;d.contactCamera.backgroundColor=Color.black;d.contactCamera.clearFlags=CameraClearFlags.SolidColor;d.contactCamera.enabled=false;
   var camera=new GameObject("Actual contact camera location marker").transform;camera.position=new Vector3(0,-.8f,0);Part("Camera housing",PrimitiveType.Cube,Vector3.zero,new Vector3(.55f,.35f,.4f),Mat("camera",teal),camera);Part("Upward camera lens",PrimitiveType.Cylinder,new Vector3(0,.24f,0),new Vector3(.22f,.15f,.22f),Mat("camera-lens",yellow),camera);d.props=new[]{camera};d.effects=new[]{g.GetComponent<Renderer>().sharedMaterial,Mat("snow-cutaway",new Color(.7f,.88f,1,.18f),"Yamyam/TechTen/Glass")};d.lines=new[]{Line("Upward viewing direction",yellow,.035f)};d.lines[0].SetPositions(new[]{new Vector3(0,-.35f,0),new Vector3(0,.1f,0)});d.shot.transform.position=new Vector3(7,6,-7);d.shot.transform.LookAt(new Vector3(0,.3f,0));}
  static void Boat(TechTenDemo d){var wood=Mat("wood",new Color(.38f,.22f,.1f));var rail=Mat("trim",yellow);Part("Boat bottom",PrimitiveType.Cube,new Vector3(0,-.1f,0),new Vector3(2.25f,.25f,4.6f),wood);for(int s=-1;s<=1;s+=2){Part("Hull wall "+s,PrimitiveType.Cube,new Vector3(s*1.13f,.5f,0),new Vector3(.18f,1.3f,4.6f),wood);Part("Gunwale "+s,PrimitiveType.Cube,new Vector3(s*1.13f,1.18f,0),new Vector3(.24f,.12f,4.7f),rail);Part("Hull end "+s,PrimitiveType.Cube,new Vector3(0,.5f,s*2.3f),new Vector3(2.4f,1.3f,.2f),wood);}for(int i=-3;i<=3;i++)Part("Deck plank "+i,PrimitiveType.Cube,new Vector3(i*.3f,.06f,0),new Vector3(.28f,.04f,4.4f),wood);
   var water=Mat("ocean",new Color(.09f,.43f,.6f));water.SetVector("_MaskRect",new Vector4(-1.04f,1.04f,-2.2f,2.2f));var outer=Part("Ocean intersecting hull",PrimitiveType.Plane,new Vector3(0,.67f,0),new Vector3(.9f,1,.9f),water);
