  static void Plane(TechTenDemo d){var root=new GameObject("Stationary cargo aircraft").transform;var grey=Mat("aircraft",new Color(.68f,.75f,.79f));Part("Fuselage",PrimitiveType.Capsule,Vector3.zero,new Vector3(1,3.2f,1),grey,root).localRotation=Quaternion.Euler(90,0,0);Part("Main wings",PrimitiveType.Cube,new Vector3(0,0,.15f),new Vector3(6,.13f,1.1f),grey,root);Part("Tail wings",PrimitiveType.Cube,new Vector3(0,.2f,-2.1f),new Vector3(2.7f,.12f,.75f),grey,root);Part("Vertical tail",PrimitiveType.Cube,new Vector3(0,.75f,-2.3f),new Vector3(.14f,1.3f,.9f),grey,root);Part("Cockpit",PrimitiveType.Sphere,new Vector3(0,.22f,2.5f),new Vector3(.78f,.6f,.8f),Mat("windows",teal),root);
