  static Transform Robot(string name,Color color,bool rifle){var t=new GameObject(name).transform;var shell=Mat("robot-"+name,color);var metal=Mat("joint",new Color(.16f,.2f,.23f));Part("Armored torso",PrimitiveType.Capsule,new Vector3(0,.6f,0),new Vector3(.6f,.43f,.4f),shell,t);Part("Helmet",PrimitiveType.Sphere,new Vector3(0,1.05f,0),new Vector3(.43f,.42f,.42f),shell,t);Part("Visor",PrimitiveType.Cube,new Vector3(0,1.07f,-.2f),new Vector3(.3f,.13f,.06f),Mat("visor",teal),t);for(int s=-1;s<=1;s+=2){Part("Upper leg",PrimitiveType.Capsule,new Vector3(s*.17f,.22f,0),new Vector3(.19f,.25f,.19f),metal,t);Part("Boot",PrimitiveType.Cube,new Vector3(s*.17f,.05f,-.08f),new Vector3(.22f,.13f,.35f),shell,t);Part("Shoulder",PrimitiveType.Sphere,new Vector3(s*.36f,.78f,0),Vector3.one*.26f,shell,t);Part("Arm",PrimitiveType.Capsule,new Vector3(s*.36f,.55f,-.05f),new Vector3(.16f,.22f,.16f),metal,t);}Part("Backpack",PrimitiveType.Cube,new Vector3(0,.65f,.23f),new Vector3(.4f,.45f,.2f),metal,t);if(rifle)Part("Rifle",PrimitiveType.Cube,new Vector3(.34f,.58f,-.45f),new Vector3(.16f,.18f,.7f),metal,t);else Part("Mining drill",PrimitiveType.Cylinder,new Vector3(.4f,.45f,-.3f),new Vector3(.2f,.3f,.2f),yellow==color?shell:Mat("drill",yellow),t).localRotation=Quaternion.Euler(90,0,0);return t;}
  static void Workers(TechTenDemo d){for(int side=-1;side<=1;side+=2)for(int block=0;block<8;block++)Part("Fixed lane wall",PrimitiveType.Cube,new Vector3(block-.5f*7,.16f,side*1.35f),new Vector3(.96f,.32f,.2f),Mat("lane-wall",new Color(.22f,.28f,.3f)));d.actors=new Transform[4];for(int i=0;i<4;i++)d.actors[i]=Robot(d.stage==2?"Harvesting worker "+i:i==0?"Mining worker":"Blocking unit "+i,d.stage==2||i==0?yellow:red,false);for(int i=0;i<3;i++){var c=Part("Mineral crystal "+i,PrimitiveType.Cube,new Vector3(3+i*.25f,.3f,(i-1)*.3f),new Vector3(.25f,.7f,.25f),Mat("mineral",teal));c.rotation=Quaternion.Euler(15,35,i*20);}d.props=new Transform[0];d.lines=new[]{Line("Harvest destination",teal,.04f)};d.shot.transform.position=new Vector3(7,7,-10);d.shot.transform.LookAt(new Vector3(0,.4f,0));}
